import sympy
from sympy.combinatorics import PermutationGroup
from sympy.combinatorics.named_groups import SymmetricGroup, AlternatingGroup, CyclicGroup, DihedralGroup
from sympy.matrices import eye, zeros

# Top-level setup: named object bindings
S3 = SymmetricGroup(3)
S4 = SymmetricGroup(4)
A4 = AlternatingGroup(4)
D4 = DihedralGroup(4)
C4 = CyclicGroup(4)
Z2 = CyclicGroup(2)
Z3 = CyclicGroup(3)
Z4 = CyclicGroup(4)
Z6 = CyclicGroup(6)
trivial = CyclicGroup(1)

I2 = eye(2)
I3 = eye(3)
O2 = zeros(2, 2)
O3 = zeros(3, 3)

def conditions(witness) -> list[bool]:
    # H_1: G is generated by a, b satisfying a^2 = 1, b^3 = 1, (ab)^3 = 1
    h1_ok = False
    try:
        def generates(G, a, b):
            id_el = G.identity
            seen = {id_el}
            queue = [id_el]
            gens = [a, b]
            while queue:
                curr = queue.pop(0)
                for g in gens:
                    nxt = curr * g
                    if nxt not in seen:
                        seen.add(nxt)
                        queue.append(nxt)
            return len(seen) == G.order()

        if isinstance(witness, tuple) and len(witness) == 3:
            G, a, b = witness
            if hasattr(G, 'identity') and hasattr(G, 'order'):
                id_el = G.identity
                if a**2 == id_el and b**3 == id_el and (a*b)**3 == id_el:
                    if generates(G, a, b):
                        h1_ok = True
        else:
            G = witness
            if hasattr(G, 'identity') and hasattr(G, 'order'):
                id_el = G.identity
                order_G = G.order()
                if order_G <= 100:
                    if hasattr(G, 'elements'):
                        elements = list(G.elements)
                    elif hasattr(G, 'generate'):
                        elements = list(G.generate())
                    else:
                        elements = []
                    
                    for a in elements:
                        if a**2 != id_el: continue
                        for b in elements:
                            if b**3 != id_el: continue
                            if (a*b)**3 != id_el: continue
                            if generates(G, a, b):
                                h1_ok = True
                                break
                        if h1_ok:
                            break
    except Exception:
        h1_ok = False

    # neg_Q: G is not isomorphic to A_4
    neg_q_ok = False
    try:
        if isinstance(witness, tuple) and len(witness) == 3:
            G = witness[0]
        else:
            G = witness
        
        A_4 = AlternatingGroup(4)
        if hasattr(G, 'is_isomorphic'):
            neg_q_ok = not G.is_isomorphic(A_4)
    except Exception:
        neg_q_ok = False

    return [h1_ok, neg_q_ok]

CONDITION_LABELS = [
    "H_1: G is generated by a, b satisfying a^2 = 1, b^3 = 1, (ab)^3 = 1",
    "¬Q: G is not isomorphic to A_4"
]

